.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('2306-2', 'CEL Seminar - Dr. Camille Barchers from the University of Massachusettes, Amherst', '/2306-2/', 'April 12th, 2022 09:30 pm – 11:00pm Title: Games&Planning in the United States Camille Barchers is an Assistant Professor of Regional Planning at University of Massachusetts Amherst. Camille Barchers has practiced as a regional planner throughout Florida, the Southeast and mid-Atlantic. Prior to joining LARP, Camille taught in the Leadership Education and Development program at the Georgia Institute of Technology. Camille’s work examines how planners use technology and how it changes the way we engage with the public. Her research interests include community engagement via information & communication technology, big data applications for equitable long-range planning, and the interaction between land use & transportation planning. Zoom Link: Zoom Link: https://snu-ac-kr.zoom.us/j/93590454443 Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025