INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('2320-2', 'CEL Seminar - Dr. Wei Zhang', '/2320-2/', 'August 27th, 2021 9:30-10:30am Title: Causality in Urban/Building Energy Modeling Wei Zhang, PhD, is a researcher at Harvard University. Wei’s research focuses on the zero-energy building and smart building technology. All his research is demonstrated at the Harvard Center for Green Buildings and Cities (CGBC), which is the frontline zero energy house platform. https://snu-ac-kr.zoom.us/j/85868902332 Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('2324-2', 'CEL Seminar - Professor Chaosu Li', '/2324-2/', 'August 27th, 2021 11:00-12:00pm Title: Urban Form and Climate Resilience: Evidence from Extreme Weather Events in Macau Chaosu Li is an assistant professor of urban planning in the Urban Governance and Design Thrust at Hong Kong University of Science and Technology (Guangzhou Campus). Previously, he was an assistant professor and the program coordinator of the Urban Planning and Design Graduate Program at City University of Macau. Dr. Li received his Ph.D. in City and Regional Planning from UNC-Chapel Hill in 2018. His work has been published in Renewable and Sustainable Energy Reviews, Environment and Planning A, Journal of Planning Education and Research, Energy and Buildings, Land Use Policy, Sustainable Cities and Society, Journal of Environmental Planning and Management, plus other journals.. https://snu-ac-kr.zoom.us/j/82537928845 Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 J