INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('astar-tour-in-sinapore', 'A*STAR tour in Sinapore', '/astar-tour-in-sinapore/', 'January 26th, 2026 Members of the CEL visited A*STAR with Professor Lai and students from Tsinghua University.The trip fostered valuable international exchange and deepened CEL lab’s engagement with AI-driven planning and design research. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('cel-academic-trip-in-singapore', 'CEL Academic Trip in Singapore', '/cel-academic-trip-in-singapore/', 'January 25th – 27th, 2026 Professor Quan and lab members visited Singapore to attend AAAI workshop and a sequential of academic communications. Day 1｜AAAI Workshop: AI Meets Planning On the first day, CEL lab members participated in an AAAI workshop , where we learned from leading scholars and senior researchers about cutting-edge applications of artificial intelligence in urban and regional planning . The workshop offered valuable insights into how AI-driven methods are reshaping planning research and practice, inspiring new perspectives for future interdisciplinary exploration. Day 2｜Academic Exchange at A*STAR On the second day, together with Professor Lai and his students, as well as researchers from Professor Laiyuan’s lab at Tsinghua University , CEL lab members visited A*STAR (Agency for Science, Technology and Research) in Singapore. Through on-site visits and in-depth discussions, we gained a deeper understanding of Singapore’s research ecosystem, ongoing AI-related projects, and collaborative research models, fostering meaningful academic exchange across institutions and countries. Day 3｜AI-aided Participatory Planning at NUS The final day was spent at the National University of Singapore (NUS) , where we attended the workshop and lecture titled “AI-aided Design for Participatory Planning and Design.” The session explored how AI tools can support participatory processes in planning and design, bridging technology, stakeholders, and decision-making. We were also honored to receive invitations from Singaporean faculty members for further academic learning and exchange, opening up new possibilities for future collaboration. {"ARInfo":{"IsUseAR":false},"Version":"1.0.0&#8243;,"MakeupInfo":{"IsUseMakeup":false},"FaceliftInfo":{"IsChangeEyeLift":false,"IsChangeFacelift":false,"IsChangePostureLift":false,"IsChangeNose":false,"IsChangeFaceChin":false,"IsChangeMouth":false,"IsChangeThinFace":false},"BeautyInfo":{"SwitchMedicatedAcne":false,"IsAIBeauty":false,"IsBrightEyes":false,"IsSharpen":false,"IsOldBeauty":false,"IsReduceBlackEyes":false},"HandlerInfo":{"AppName":2},"FilterInfo":{"IsUseFilter":false}} Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('cel-seminar', 'CEL Seminar - Applications of Interpretable Machine Learning in Sustainable Built Environment Studies', '/cel-seminar/', 'May 1st, 2023 10:00AM-11:00 Title: Applications of Interpretable Machine Learning in Sustainable Built Environment Studies Professor Chao Liu is an assistant professor at the College of Architecture and Urban Planning, Tongji University in China. She is also the director of the Su-Smart City Lab. She received her PhD degree from the University of Florida. Professor Liu is funded by the Chinese NSF project and several national and provincial-level scientific projects. She has published over 30 peer-reviewed papers. Her research and practical interests are focused on AI applications in sustainable cities, making her an expert in this field. Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May