INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('conference-professor-steven-jige-quan-at-the-7th-lh-global-business-convention-wsce-2026', '[Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026)', '/conference-professor-steven-jige-quan-at-the-7th-lh-global-business-convention-wsce-2026/', '[Event Information] Event: The 7th LH Global Business Convention (GBC), World Smart City Expo 2026 Theme: Future Cities in an Era of Uncertainty Location: BEXCO, Busan, South Korea Date: September 10, 2026 Presentation Title: AI-Assisted Participatory Planning Support Presenter: Professor Steven Jige Quan, Director of City Energy Lab, Seoul National University Organizer: Korea Land & Housing Corporation (LH) Summary Professor Steven Jige Quan, Director of City Energy Lab at Seoul National University, participated as a speaker at the 7th LH Global Business Convention, held during the World Smart City Expo 2026 (WSCE 2026) in Busan, South Korea. At the convention, Professor Quan delivered a presentation titled “AI-Assisted Participatory Planning Support.” The presentation explored the potential of artificial intelligence to enhance participatory urban planning by supporting stakeholder engagement, facilitating communication, and promoting collaborative decision-making. Drawing on research into AI-assisted planning support systems, the presentation highlighted how emerging AI technologies, including large language models and generative AI, can help stakeholders articulate their needs, explore alternative planning scenarios, and participate more actively in urban design and planning processes. The presentation emphasized the importance of integrating AI technologies into participatory planning frameworks to support more inclusive, transparent, and collaborative approaches to sustainable urban development. The convention provided an opportunity to share research on AI-assisted urban planning with international experts and discuss the evolving role of artificial intelligence in shaping future cities. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('conference-workshop-city-energy-lab-at-the-ai4cities-3-international-conference-and-summer-workshop', '[Conference & Workshop] City Energy Lab at the AI4CITIES-3 International Conference and Summer Workshop', '/conference-workshop-city-energy-lab-at-the-ai4cities-3-international-conference-and-summer-workshop/', '[Event Information] • Event: The 3rd AI4CITIES International Conference and 2nd AI4CITIES Summer Workshop • Theme: Symbiotic Planning: Human-AI Co-creating the Future Experimental Island • Location: Fuxing Island Future City Experimental Zone, Shanghai, China • Opening Date: July 15, 2026 Summary Professor Steven Jige Quan and City Energy Lab members Jianqi, Yeqin, and Inseong participated in the 3rd AI4CITIES International Conference and 2nd AI4CITIES Summer Workshop, held at the Fuxing Island Future City Experimental Zone in Shanghai. Under the theme “Symbiotic Planning: Human-AI Co-creating the Future Experimental Island,” the event brought together experts, scholars, practitioners, and students from urban planning, architecture, artificial intelligence, computer science, and related disciplines. The conference explored emerging theories, technological developments, and practical applications of AI-enabled urban planning and development. Professor Quan participated as a panelist in the roundtable discussion titled “Urban Spatial Agent” and "Quantum AI-aided Design (QAID)." City Energy Lab members Jianqi, Yeqin, and Inseong also participated in the event and contributed to the summer workshop activities. A team led by Professor Quan and Jianqi, with the participation of Yeqin and Inseong, received the Best Future Scenario Award . The award recognized the team’s contribution to developing a future-oriented urban scenario through human-AI collaboration. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
