INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('first-lab-meeting-and-celebration-on-chinese-teachers-day', 'First Lab meeting and Celebration on Chinese Teacher''s Day', '/first-lab-meeting-and-celebration-on-chinese-teachers-day/', 'The Autumn New Lab Member Meeting was held on September 10, 2024. To mark the occasion, all lab members surprised the team with a celebratory cake for Chinese Teacher''s Day. Happy Chinese Teacher''s Day, professor!! Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('guest-lecture', 'CEL Seminar - Urban morphology and spatiotemporal variabilities of urban surface temperature: Evidence from remote sensing and statistics', '/guest-lecture/', 'April 7th, 2023 10:30am-11:30am Title: Urban morphology and spatiotemporal variabilities of urban surface temperature: Evidence from remote sensing and statistics Yujin Park is an assistant professor in the Department of Urban Planning and Real Estate at Chung-Ang University. Prior to joining Chung-Ang, she was an assistant professor in the Department of City Planning and Real Estate Development at Clemson University, SC, USA. Dr. Park''s research aims at advancing understanding of sustainable urban form and design in 3D, with an emphasis on exploring the trade-offs between different design strategies. Her recent work examines the varied role of urban trees and green spaces in moderating urban temperatures leveraging the capabilities of 3D city modeling, remote sensing, and statistical techniques. She received her Ph.D. in City and Regional Planning from Ohio State University in 2020, and her MS in City Planning and BA in Humanities from Seoul National University. Dr. Park currently serves as the editorial board member of Journal of Korean Planners Association and the book review editor of Journal of Planning Literature. Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('guest-lecture-fine-scale-climate-projections-reveal-spatial-heterogeneity-in-future-aedes-suitability-across-southeast-asia', '[Guest Lecture] Fine-Scale Climate Projections Reveal Spatial Heterogeneity in Future Aedes Suitability Across Southeast Asia', '/guest-lecture-fine-scale-climate-projections-reveal-spatial-heterogeneity-in-future-aedes-suitability-across-southeast-asia/', '[Invited Colloquium] Fine-Scale Climate Projections Reveal Spatial Heterogeneity in Future Aedes Suitability Across Southeast Asia [Lecture Information] Date & Time: September 21, 2026, 4:00–5:00 PM Venue: Room 113, Building 82, Graduate School of Environmental Studies, Seoul National University Hosted by: City Energy Lab & BK21 Four Program, Graduate School of Environmental Studies, Seoul National University Moderator: Prof. Quan Jige (Graduate School of Environmental Studies, Seoul National University) [Highlight] The presentation explored the future habitat suitability of key mosquito vectors, specifically Aedes aegypti and Aedes albopictus , across Southeast Asian regions by leveraging high-resolution climate projections and detailed spatial datasets. Associate Professor Luo highlighted that suitable habitats for both vector species are projected to expand significantly, increasing by more than 10% across the region by the year 2050. The talk emphasized that addressing vector-borne disease risks requires moving beyond macro-level climate models to examine local spatial variations and fine-scale environmental factors. Through empirical analysis, Associate Professor Luo demonstrated the contrasting roles played by ongoing urbanization and broader climatic shifts in driving mosquito distribution patterns and associated arboviral transmission risks. He introduced how spatial analytics, geographic modeling, and high-resolution environmental data can uncover localized vulnerabilities, enabling policymakers and urban planners to design more targeted, context-sensitive public health interventions across diverse regional landscapes. Moderated by Prof. Quan Jige, the colloquium provided an invaluable platform for academic exchange, bringing together students, faculty, and researchers in urban planning, spatial analytics, and environmental studies. The session concluded with a vibrant discussion on how spatial data science and interdisciplinary research can better inform sustainable urban planning, climate adaptation strategies, and regional health security. Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('guest-lecture-integrated-landscape-approaches-to-energy-planning', '[Guest Lecture] Integrated Landscape Approaches to Energy Planning', '/guest-lecture-integrated-landscape-approaches-to-energy-planning/', '[Event Information] • Speaker: Yekang Ko, PhD • Affiliation: Associate Professor of Landscape Architecture, University of Michigan • Date: June 16, 2026 • Time: 3:00–4:00 p.m. • Venue: SNU GSES Building 82, Room 114 Highlight The City Energy Lab invited Professor Yekang Ko from the University of Michigan to deliver a lecture titled “Integrated Landscape Approaches to Energy Planning.” The talk addressed the spatial challenges associated with renewable energy expansion, electrification, and energy conservation. While these strategies are essential for climate change mitigation and carbon neutrality, Professor Ko emphasized that the energy transition extends beyond technical infrastructure and involves critical questions related to land use, social equity, ecological integrity, and community well-being. Professor Ko introduced the Integrated Landscape Approach as a framework for addressing these interconnected challenges through transdisciplinary research, stakeholder participation, multifunctionality, and sustainability. She proposed combining the landscape transect and the concept of the energyshed to connect local, place-based conditions with broader energy systems across urban, suburban, rural, and coastal landscapes. The lecture demonstrated how different landscape contexts present distinct opportunities, constraints, and value streams for renewable energy development. By recognizing these differences, the framework can support context-sensitive energy planning while promoting equitable, ecologically responsible, and multifunctional landscapes. The event provided an opportunity for students and researchers to discuss how landscape planning and design can contribute to a more inclusive and climate-resilient energy transition. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('guest-lecture-leveraging-unsupervised-machine-learning-techniques-to-understanding-sustainable-and-equitable-transportation', 'Guest Lecture: Leveraging Unsupervised Machine Learning Techniques to Understanding Sustainable and Equitable Transportation', '/guest-lecture-leveraging-unsupervised-machine-learning-techniques-to-understanding-sustainable-and-equitable-transportation/', 'October 20th, 2025, 5 – 6pm Guest Lecture: Leveraging Unsupervised Machine Learning Techniques to Understanding Sustainable and Equitable Transportation Dr. Shengxiao (Alex) Li, Assistant Professor at the National University of Singapore (NUS) Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 20