INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('invited-colloquium-seconds-to-decades-high-frequency-analytics-to-low-frequency-urban-design-through-community-driven-digital-twins-lecture-information', '[Invited Colloquium] Seconds to Decades: High-Frequency Analytics to Low-Frequency Urban Design through Community-driven Digital Twins [Lecture Information]', '/invited-colloquium-seconds-to-decades-high-frequency-analytics-to-low-frequency-urban-design-through-community-driven-digital-twins-lecture-information/', '[Invited Colloquium] Fine-Scale Climate Projections Reveal Spatial Heterogeneity in Future Aedes Suitability Across Southeast Asia [Lecture Information] Date & Time: October 15, 2026, 4:00–5:00 PM Venue: Room 113, Building 82, Graduate School of Environmental Studies, Seoul National University Hosted by: City Energy Lab & BK21 Four Program, Graduate School of Environmental Studies, Seoul National University Moderator: Prof. Quan Jige (Graduate School of Environmental Studies, Seoul National University) [Highlight] The presentation explored how advances in artificial intelligence (AI), big data analytics, and sensor networks influence human perceptions and experiences of urban spaces, as well as approaches to urban design. Professor Yang highlighted how high-frequency, real-time data analytics at the scale of seconds and minutes can address urban climate risks, such as urban heat islands and flooding, and inform long-term urban design and redevelopment decisions spanning years to decades. The talk emphasized that creating sustainable, resilient, and socially inclusive urban environments requires integrating community-driven urban digital twins with district-scale urban systems design. Drawing on empirical research from the 10-year Tokyo Smart City Studio in Tokyo and the 6-year Urban Systems Design Workshop focused on Atlanta''s airport city in the United States, Professor Yang introduced a multi-stakeholder collaborative framework. He demonstrated how data analytics, ecological design, and spatial modeling can bridge high-frequency urban monitoring with long-term urban planning, enabling decision-makers and urban design practitioners to develop more targeted, context-sensitive climate adaptation strategies across diverse urban scales. Moderated by Prof. Quan Jige, the colloquium provided an invaluable platform for academic exchange, bringing together students, faculty, and researchers in urban planning, spatial analytics, and environmental studies. The session concluded with a vibrant discussion on how spatial data science and interdisciplinary research can better inform sustainable urban planning, climate adaptation strategies, and community-driven digital twin applications. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('invited-talks-academic-exchange-invited-talks-in-shenzhen-and-hong-kong', '[Invited Talks & Academic Exchange] Invited Talks in Shenzhen and Hong Kong', '/invited-talks-academic-exchange-invited-talks-in-shenzhen-and-hong-kong/', '[Visit Information] • Period: April 8–10, 2026 • Activities: Invited lectures and academic exchange meetings Highlight Professor Steven Jige Quan visited leading universities in Shenzhen and Hong Kong during April 8–10, 2026, where he delivered invited talks on AI-assisted environmental planning and sustainable urban systems. Summary During the academic visit, Professor Steven Jige Quan gave invited presentations at Tsinghua Shenzhen International Graduate School, The University of Hong Kong, and City University of Hong Kong. The lectures introduced recent research from the City Energy Lab on artificial intelligence-assisted environmental planning and design, urban energy systems, and sustainable city analytics. The presentations explored how AI technologies can support environmental planning, urban perception analysis, and public participation in sustainable urban development. The visit also provided opportunities for interdisciplinary exchange with scholars and students in architecture, urban planning, and environmental studies. Invited Talks • Tsinghua Shenzhen International Graduate School • The University of Hong Kong • City University of Hong Kong Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
