INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('open-lecture-urban-form-and-historical-roots-cities-in-china-and-japan', 'Open Lecture: Urban form and historical roots: Cities in China and Japan', '/open-lecture-urban-form-and-historical-roots-cities-in-china-and-japan/', 'Topic Urban form and historical roots: Cities in China and Japan Date/Time/Venue 2019. 03. 28.(Thur), 14:00 ~ 15:30 2F Open Library, GESE (Bidg 82), SNU Details Shulan Fu is currently an associate professor in the Department of Urban Planning at Zhejiang University, China and also a KJAS-Kyujanggak Fellow (2018-2019) at Seoul National University The lecture introduces important concepts in the development of historical cities in China and Japan, and compares the urban systems in the two countries to further explain the historical roots of their contemporary urban forms. Everyone interested is welcomed to join Photos Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind?');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('opportunity', 'Opportunity', '/opportunity/', 'Research Assistant Opportunity for Undergraduate, Master and Ph.D. students in SNU The City Energy Lab is hiring research assistants with one or more interests on the following topics: - big data analytics on building energy and microclimate - comparative study on urban form and energy in Asian cities - life-cycle building energy - transportation energy in the new era of shared, electric and autonomous vehicles - urban metabolism - design computation for sustainable neighborhoods Post-doc Fellow Opportunity The City Energy Lab encourages post-doc applications under the Korea Research Fellowship (KRF) program. The applicant should demonstrate his/her strong background and high motivation in city energy studies. A well-written research plan is required. Doctoral Application Applicants with the background and interest in urban form and energy are encouraged to contact Prof. Steven Jige Quan. Successful Ph.D. applicants should have the strong related background, great enthusiasm for the study, high self-discipline in research projects, and fluent English speaking and writing skills.');
