INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('participation-the-annual-meeting-of-the-resilient-city-committee-of-the-china-urban-science-research-association-and-the-international-symposium-on-urban-sustainable-development-in-fuzhou', 'Professor Quan''s lecture at the Annual Meeting of the Resilient City Committee of the China Urban Science Research Association and the International Symposium on Urban Sustainable Development in Fuzhou.', '/participation-the-annual-meeting-of-the-resilient-city-committee-of-the-china-urban-science-research-association-and-the-international-symposium-on-urban-sustainable-development-in-fuzhou/', 'July 8th-11th Title: Professor Quan''s lecture at the Annual Meeting of the Resilient City Committee of the China Urban Science Research Association and the International Symposium on Urban Sustainable Development in Fuzhou. Associate Professor Quan Jige provided an in-depth discussion on effectively combining computational thinking to construct accurate energy models, promoting cross-system integration using systems thinking, and deepening the understanding of the complexities of urban energy systems through design thinking. Utilizing research projects from the City Energy Lab at SNU as examples, the presentation covered the design of smart communities and future energy-resilient cities, emphasizing the importance of interdisciplinary approaches in achieving urban sustainability. The discussion also envisioned the future development of urban energy systems and explored their theoretical and practical applications. Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('participation-the-annual-meeting-of-the-resilient-city-committee-of-the-china-urban-science-research-association-and-the-international-symposium-on-urban-sustainable-development-in-fuzhou-2', 'Professor Quan''s lecture at the Annual Meeting of the Resilient City Committee of the China Urban Science Research Association and the International Symposium on Urban Sustainable Development in Fuzhou.', '/participation-the-annual-meeting-of-the-resilient-city-committee-of-the-china-urban-science-research-association-and-the-international-symposium-on-urban-sustainable-development-in-fuzhou-2/', 'July 8th-11th Title: Participation: the Annual Meeting of the Resilient City Committee of the China Urban Science Research Association and the International Symposium on Urban Sustainable Development in Fuzhou. From July 8 to 11, 2024, the Annual Meeting of the Resilient City Committee of the China Urban Science Research Association and the International Symposium on Urban Sustainable Development, supported by the School of Architecture at Tianjin University, was held at Jinjiang Building, Qishan Campus of Fuzhou University. This conference, themed "Sustainable Development and Resilient Cities," aimed to explore how to promote urban sustainable development from the perspective of ecological resilience, deepen international cooperation, learn from each other, share ideas on resilient city development, and jointly formulate strategies for green and low-carbon development to create a sustainable urban future. The conference was guided by the China Urban Science Research Association and jointly organized by the Resilient City Committee of the China Urban Science Research Association, the International Association of Chinese Planning (IACP), and Fuzhou University. It was hosted by the School of Architecture and Urban Planning at Fuzhou University, the School of Architecture at Tianjin University, the Fujian Regional Architecture Research Center, the Fujian Fuda Architectural Planning and Design Research Institute Co., Ltd., the Sustainable Urban Research Institute of Fuzhou City, the Key Engineering Technology Innovation Center for Land and Space Planning and Governance by the Ministry of Natural Resources, the Key Research Base for Humanities and Social Sciences of Ordinary Higher Education Institutions in Tianjin - "Coastal City Safety and Intelligent Disaster Prevention," and the Key Laboratory for Land and Space Analysis and Simulation Digital Technology in Fujian Province. The event received strong support from the Fujian Planning Society, the Fujian Land Society, the Fujian Landscape Architecture Society, the Fujian Urban Science Society, and the Fuzhou Planning Museum. The conference attracted over 20 renowned international scholars from the United States, the United Kingdom, South Korea, Singapore, and Hong Kong, as well as more than 120 participants from over 30 domestic universities, research institutions, and design institutes. The attendees engaged in in-depth discussions on cutting-edge concepts and innovative practices related to resilient cities. Professor Steven Jige Quanprovided an in-depth discussion on effectively combining computational thinking to construct accurate energy models, promoting cross-system integration using systems thinking, and deepening the understanding of the complexities of urban energy systems through design thinking. Utilizing research projects from the City Energy Lab at SNU as examples, the presentation covered the design of smart communities and future energy-resilient cities, emphasizing the importance of interdisciplinary approaches in achieving urban sustainability. The discussion also envisioned the future development of urban energy systems and explored their theoretical and practical applications. Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('previous-members', 'Previous Members', '/previous-members/', 'ALUMNI Hyun Mi Kang Urban and Regional Planning Academic Background: Hongik University - Department of Architecture Current Employment: Samil PwC Graduation year: 2018 Thesis Title: Participatory low impact development(LID) process based on a geodesign framework : Nam-gu in Incheon as a case study. Dang Thi Huong Giang Urban and Regional Planning Academic Background: Vietnam National University – Hanoi University of Science Current Employment: - Graduation year: 2019 Thesis Title: The exploration of energy performance of Seoul typical neighborhoods in a new era : With the penetration of electric vehicles and renewable energy system. Bola Ju (MICHELLE) Urban Planning Academic Background: Handong Global University - Urban and Environmental Engineering Current Position & Program: Doctor of Design student, Graduate School of Design, Harvard Univesity Graduation year: 2019 Thesis Title: A study on Potential Carbon Mitigation Impact with Microgrid Implementation in Typical Residential Neighborhood in Seoul: An Integrated Urban System Approach. JEONG MIN EUN Urban and Regional Planning Academic Background: Chung Ang University - Sociology, Urban Design and Studies Current Employment: Hyundai Motor Company Graduation year: 2020 Thesis Title: The association between urban form and perceived safety of urban environment : A case study in New York City, USA. Inkoo Kang Urban and Regional Planning Academic Background: Korea University - Public administration and French literature Current Position & Program: PhD student, Department of Civil and Urban Engineering, New York University Graduation year: 2020 Thesis Title: Impact of Public Space on City Imageability: The Case of Urban Regeneration in Seoul at the Neighborhood Scale. KYUNG DO KIM Urban and Regional Planning Academic Background: Inha University - Department of Architecture Current Employment: Jeju Research Institute Graduation year: 2020 Thesis Title: Exploration of Residential Electricity Consumption in Different Neighborhood Contexts in Seoul under Progressive Electricity Tariff System. Nadia Urban and Regional Planning Academic Background: Geneva University(Switzerland) - Department of Geography and Environment Current Employment: SIG - Industrial Service of Geneva (Switzerland) Graduation year: 2020 Thesis Title: Green rooftops'' mitigation potential on Urban Heat Island, Case study in summer, in Seoul. Sanghoon Lee Urban and Regional Planning Academic Background: Korea University - Department of Architecture Current Employment: Hyundai Motor Graduation year: 2020 Thesis Title: A Study of the Relationship between Urban Density, Land Use and Embodied Energy in Urban Environment. HYUNKYUNG KIM (STELLA) Urban and Regional Planning Academic Background: Handong Global University - Computer Science and Global Entrepreneurship Current Employment: Korea Research Institute for Human Settlements Graduation year: 2020 Thesis Title: Analyzing the influential factors of the elderly daytime mobility in Seoul: using big data of de facto population in Seoul. Junoh Kim Urban and Regional Planning Academic Background: Sungkyunkwan University Current Position & Program: PhD student, School of Sustainable Energy Engineering, Simon Fraser University, Canada Graduation year: 2022 Thesis Title: Investigation of the Effect of Building Energy Retrofit Program in Seoul Under the Climate Change. Haylin Kim Urban and Regional Planning Academic Background: Simon Fraser University (Canada) - Environmental Systems major Current Position & Program: Google Korea Graduation year: 2022 Thesis Title: Examining Electricity Energy Self-Sufficiency through Rooftop Photovoltaic Microgrid and Electric Vehicle Integration in Future Gangnam-gu, Seoul. Jiyeon Park Urban and Regional Planning Academic Background: Hankuk University of Foreign Studies - Language & Diplomacy major, Japanese Literature and Culture minor / Current Employment: - / Graduation year: 2023 / Thesis Title: Forecasting Building Energy Demand in Seoul');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('principal_investigator', 'Principal Investigator', '/principal_investigator/', 'Quan, Steven Jige Steven Jige Quan is the director of City Energy lab. He is Professor in the Department of Urban Planning at the Graduate School of Environmental Studies (GSES), Seoul National University, South Korea. His research focuses on smart and sustainable urban systems, urban form and energy, AI-aided design (AIAD), and sustainable zoning systems. Prior to academia, he worked as Chief Planner in No. 3 Department of Comprehensive Planning at Beijing Tsinghua Urban Planning & Design Institute, where he led teams that won several international urban design competitions. He also served as Lecturer at Georgia Institute of Technology. Steven holds a B.Arch. and an M.Eng. in Urban Planning from Tsinghua University, China, and an M.Sc. in Computer Science and a PhD in City and Regional Planning from Georgia Institute of Technology. Academic background 2016 Ph.D., City and Regional Planning, Georgia Institute of Technology 2022 Master, Computer Science, Georgia Institute of Technology 2005 Master, Urban Planning, Tsinghua University 2002 Bachelor, Architecture, Tsinghua University Major Work Experience 2026- Present Professor, Seoul National University 2021- 2026 Associate Professor, Seoul National University 2017-2021 Assistant Professor, Seoul National University 2016-2017 Lecturer & Postdoctoral Fellow, Georgia Institute of Technology 2016-2017 Assistant Director, Sino-US Eco Urban Lab, Georgia Institute of Technology and Tongji University 2010-2011 Chief Planning and Design Consultant (Part-time), Center of Urban Planning and Design, United Architect & Engineers CO., Ltd 2005-2009 Chief Planner, No. 3 Department of Comprehensive Planning, Beijing Tsinghua Urban Planning & Design Institute Editorial Services Guest Editor, Special Issue Quantum Computing and the City, Cities. 2026-present. (SSCI journal) Editorial Board, Journal of Planning Education and Research. 2024 – present. (SSCI journal) Editorial Panel (Associate Editor), Municipal Engineer. 2022 – present. (SCI journal) Associate Editor, ACM Transactions on Social Computing. 2025-present. (Scopus journal) Editorial Board, Environmental Policy and Administration. 2023 – present. (KCI journal) Editorial Board, Regional Studies. 2022 – present. (KCI journal) Conference Activities 2026 Major Organizer, the 2nd Workshop on AI for Urban Planning, the 40th Annual AAAI Conference on Artificial Intelligence, Singapore, January 26. 2025 Organizing Committee, AI and Cities: An International Forum for Innovation and Collaboration, online, May 9-10. 2025 Major Organizer, the 1st Workshop on AI for Urban Planning, the 39th Annual AAAI Conference on Artificial Intelligence, Philadelphia, U.S., March 3. 2021 Vice Chair, the 16th Annual Conference of International Association for China Planning (IACP), Nanjing, China/Virtual, September 11-13. 2020 Vice Chair, the 15th Annual Conference of International Association for China Planning (IACP), Shenzhen, China/Virtual, December 5-13. Professional License 2009-current Registered Planner, China');
INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('professor-quan-and-lab-members-attended-aaai-2025s-workshop-the-1st-workshop-on-ai-for-urban-planning-in-philadelphia-pennsylvania-usa', 'Professor Quan and lab members attended AAAI 2025''s Workshop - The 1st Workshop on AI for Urban Planning in Philadelphia, Pennsylvania, USA', '/professor-quan-and-lab-members-attended-aaai-2025s-workshop-the-1st-workshop-on-ai-for-urban-planning-in-philadelphia-pennsylvania-usa/', 'Feb 28th - March 3rd, 2025 Title: Professor Quan and lab members attended AAAI 2025''s Workshop - The 1st Workshop on AI for Urban Planning Professor Quan as one of the Organizing Committees, hosted the workshop. Master''s student Yeonjoon Moon presented her work via the poster - ''Identify Urban Block Typology In Seoul Using Improved KMeans Clustering Method'' via poster. Master''s student Lili Lin presented her work - ''Knowledge Graph Generation from Urban Planning Texts: Climate Change Adaptation in Master Plans of New York and Shanghai'' via poster. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May