INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('professor-quan-delivered-a-lecture-on-explainable-machine-learning-in-urban-research-at-the-machine-learning-methods-forum-at-chongqing-university', 'Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University.', '/professor-quan-delivered-a-lecture-on-explainable-machine-learning-in-urban-research-at-the-machine-learning-methods-forum-at-chongqing-university/', 'Event: Environmental Planning and Design with Artificial Intelligence Date & Time: Wednesday, June 24, 2026, 2:30 PM (Beijing Time) Venue: International Conference Hall (Room 5228), 2nd Floor, School of Architecture and Urban Planning, Chongqing University, China Presentation Title: Environmental Planning and Design with Artificial Intelligence Speaker: Professor Quan Jige (Seoul National University, South Korea) Professor Quan delivered a lecture on "Environmental Planning and Design with Artificial Intelligence" at Chongqing University on June 24, 2026. The lecture explored the applications of artificial intelligence in environmental planning and design, focusing on computation, abstraction, and design. Drawing on research conducted at Seoul National University''s Urban Energy Lab, he discussed emerging opportunities for AI-assisted urban planning, sustainable urban systems, and public participation in environmental decision-making. Categories: Uncategorized 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categories NEWS Principle Investigator / Publications Uncategorized Meta Log in Entries feed Comments feed WordPress.org');
