INSERT OR REPLACE INTO pages (slug, title, url, text) VALUES ('sujin-and-chris-presented-at-cue-conference', 'Sujin and Chris Presented at CUE conference', '/sujin-and-chris-presented-at-cue-conference/', 'City Energy Lab Ph.D. students Sujin Lee and Chris Curington presented their working papers: “A pilot study on relationship between density, air pollution and building energy use: A case study of Seoul, Korea” and “Energy Policy Evolution And Urban Regime Changes In Seoul, South Korea 1996-2019: Implications For Planners” respectively at the Applied Energy Symposium: Low Carbon Cities and Urban Energy Systems in Xiamen, China October 16 th -18 th . Categories: NEWS 0 Comments Leave a Reply Cancel reply Your email address will not be published. Required fields are marked * Name * Email * Website What''s on your mind? Search for: Recent Posts [Field Trip] 2026-2 Urban Planning and Zoning Class The commencement day of Lili [Conference] Professor Steven Jige Quan at the 7th LH Global Business Convention (WSCE 2026) Professor Quan gave an online lecture on presentation title: "Examining Model Accuracy and Reliability of Explanations in Explainable Machine Learning for Urban Studies: A Case Study of Residential Building Energy Use in Seoul"at the machine learning methods forum Professor Quan delivered a lecture on "Explainable Machine Learning in Urban Research" at the Machine Learning Methods Forum at Chongqing University. Recent Comments ปั้มไลค์ on Joint Seminar with Hanyang University''s Urban Design and Spatial Analysis Lab Archives November 2026 September 2026 August 2026 May 2026 April 2026 March 2026 February 2026 December 2025 September 2025 August 2025 June 2025 February 2025 January 2025 November 2024 October 2024 April 2024 March 2024 January 2024 October 2023 July 2023 May 2023 April 2023 February 2023 November 2022 August 2022 May 2022 April 2022 March 2022 December 2021 October 2021 August 2021 October 2019 July 2019 May 2019 March 2019 June 2017 Categori