INSERT INTO courses (heading, content, sort_order) VALUES ('Urban Form and Energy – A Global Perspective', '3 credits | Lecture/Seminar | Master | Dept. of City Planning | City and Regional Planning', 0);
INSERT INTO courses (heading, content, sort_order) VALUES ('Urban Form and Energy – A Global Perspective', 'Cities significantly contribute to global energy consumptions and carbon emissions. A better understanding of the relationships between urban form and energy performance in global urban contexts is necessary to facilitate energy efficient and resilient urban development. This course aims to prepare graduate students through the introduction of contemporary theory arguments, cutting-edge modeling tools and exploratory design applications on the energy performance of urban form with a global perspective. Following the quantitative approach to define urban form, four types of energy performance and their relationships with urban form will be discussed in this course: transportation energy, building operational energy, embodied energy of buildings and infrastructures, and decentralized renewable energy. Cutting-edge urban scale energy modeling tools will be introduced to students and some of the tools will be tested in exercises to examine energy performance of different urban forms with global cultural and regulatory contexts. The course will further introduce energy-oriented planning and design methods, and the energy resilient zoning and other policy tools. The course will conclude with a discussion of integrating science, design and policy in the field of urban form and energy for energy efficient and resilient urban development.', 1);
INSERT INTO courses (heading, content, sort_order) VALUES ('Seminar in Urban and Environmental Policy: Zoning for Sustainable Development: A Global Perspective', '3 credits | Lecture/Seminar | Master | Dept. of City Planning | City and Regional Planning', 2);
INSERT INTO courses (heading, content, sort_order) VALUES ('Seminar in Urban and Environmental Policy: Zoning for Sustainable Development: A Global Perspective', 'This subject discusses economic, social, and scientific factors and necessary conditions of policies which must be considered when establishing the urban and environmental policy. And in relation to these discussion, this subject examines and evaluates major urban and environmental policies at present. This will help students to gain comprehensive understanding and analytical technique about the current policies of the fields.', 3);
INSERT INTO courses (heading, content, sort_order) VALUES ('Artificial Intelligence in Urban Planning and Design 1', '3 credits | Lecture/Seminar | Master | Dept. of City Planning | City and Regional Planning', 4);
INSERT INTO courses (heading, content, sort_order) VALUES ('Artificial Intelligence in Urban Planning and Design 1', 'Artificial intelligence (AI) has been transforming many fields including urban planning and design in recent years due to its great power to reveal complex patterns and solve difficult problems. This course aims to provide an introduction to AI and its applications in urban planning and design for graduate students who are interested in this topic. The course has three main parts: the theoretical foundation of AI and its connection with urban science and design, the prevailing AI algorithms and their application examples, 1and hands-on coding labs.', 5);
INSERT INTO courses (heading, content, sort_order) VALUES ('Artificial Intelligence in Urban Planning and Design 2', '3 credits | Lecture/Seminar | Doctoral | Dept. of City Planning | City and Regional Planning', 6);
INSERT INTO courses (heading, content, sort_order) VALUES ('Artificial Intelligence in Urban Planning and Design 2', 'This course is the second course in the course series on artificial intelligence (AI) in urban planning and design. It contains three main parts: advanced AI algorithms, applications of those algorithms, and issues in the AI applications. The course introduces sophisticated and powerful AI algorithms, including multi-objective optimization, deep learning, and reinforcement learning. These algorithms are exemplified in simplified planning and design cases. The course also discusses fundamental issues in AI application in planning and design, such as interpretability, accountability, transparency, and fairness, and introduces the concepts of explainable AI and interpretable machine learning (ML). The course concludes with a discussion on integrating domain knowledge and AI techniques and the future directions in this field.', 7);
